export type CatalogProduct = {
  sku: string
  name: string
  priceCents: number
  stock: number
  available: boolean
}

/**
 * In-memory stand-in for ERP/PIM state. `syncCatalogFromErp` bumps revision so
 * cached catalog reads change after background sync + tag invalidation.
 */
let catalogRevision = 0

const seedRows: CatalogProduct[] = [
  { sku: 'NBK-1001', name: 'Laptop 14"', priceCents: 999_00, stock: 42, available: true },
  { sku: 'PHN-2040', name: 'Phone', priceCents: 699_00, stock: 128, available: true },
  { sku: 'TAB-3300', name: 'Tablet', priceCents: 499_00, stock: 0, available: false },
  { sku: 'AUD-5510', name: 'Headphones', priceCents: 199_00, stock: 256, available: true },
  { sku: 'WCH-7700', name: 'Watch', priceCents: 299_00, stock: 18, available: true },
]

export type CatalogPayload = {
  products: CatalogProduct[]
  revision: number
  resolvedAt: string
}

export async function loadCatalogFromSource(): Promise<CatalogPayload> {
  await new Promise((resolve) => setTimeout(resolve, 100))

  const deltaCents = catalogRevision * 25
  return {
    products: seedRows.map((p) => ({
      ...p,
      priceCents: p.priceCents + deltaCents,
    })),
    revision: catalogRevision,
    resolvedAt: new Date().toISOString(),
  }
}

/** Simulates a large ERP/PIM pull; runs inside `after()` so the admin request returns quickly. */
export async function syncCatalogFromErp(): Promise<void> {
  await new Promise((resolve) => setTimeout(resolve, 2_500))
  catalogRevision += 1
}

